	static {
		this.styles = o`
    :host {
      display: block;
      --_link: #49595e;
      --_text: #000;
      --_focus-ring: ${Q(U.color.brand.red)};
    }

    :host([hidden]) {
      display: none;
    }

    footer {
      background-color: ${Q(U.color.brand.caliche)};
      color: var(--_text);
      padding-block: 48px;
      font-size: 16px;
      line-height: 1.5;
    }

    .container {
      box-sizing: border-box;
      width: 100%;
      margin-inline: auto;
      padding-inline: 12px;
    }

    a {
      color: ${Q(U.color.brand.red)};
      text-decoration: underline;
    }

    a:focus-visible {
      outline: 0;
      border-radius: 2px;
      box-shadow: 0 0 0 2px var(--_focus-ring);
    }

    hr {
      margin: 16px 0;
      color: inherit;
      border: 0;
      border-top: 1px solid currentColor;
      opacity: 0.25;
    }

    /* Logo and utility links. */
    /* Bootstrap's 12-column grid with 24px gutters, so columns line up with Quickstart's. */
    .top,
    .columns {
      display: grid;
      grid-template-columns: repeat(12, minmax(0, 1fr));
      gap: 0 24px;
    }

    .top > *,
    .columns > * {
      grid-column: span 12;
    }

    .top {
      justify-items: center;
    }

    .logo {
      display: block;
      margin-bottom: 40px;
    }

    /* A slotted logo is the site's own markup, so the site sizes its image. */
    ::slotted(a) {
      display: block;
    }

    .ua-wordmark {
      display: block;
      width: 226px;
      max-width: 100%;
      height: auto;
    }

    /* Navy lettering on a light background makes the reversed wordmark the full-color logo. */
    .ua-wordmark .lettering {
      fill: ${Q(U.color.brand.blue)};
    }

    .ua-wordmark .substrate {
      fill: ${Q(U.color.brand.white)};
    }

    /* Link lists, styled as Nav's utility variant (az.component.nav.utility.*). */
    ul {
      list-style: none;
      margin: ${Q($.margin.top)} 0 ${Q($.margin.bottom)};
      padding: 0;
    }

    .menu a {
      display: inline-flex;
      align-items: center;
      gap: 0.4em;
      font-weight: ${Q($.label.font.weight)};
      color: var(--_link);
      text-decoration: none;
      border-bottom: 2px solid transparent;
    }

    .menu a:hover,
    .menu a:focus {
      border-bottom-color: var(--_link);
    }

    .utility {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
    }

    .utility li {
      padding: 0 ${Q($.item.padding.x)};
    }

    /* Flex keeps each item's bottom margin inside its list, as in Quickstart. */
    .columns ul {
      display: flex;
      flex-direction: column;
      line-height: 1.375;
    }

    .columns li {
      display: flex;
      margin-bottom: 4px;
    }

    h2 {
      margin: 16.672px 0 10.672px;
      font-size: 16px;
      font-weight: 500;
      line-height: 1.2;
      text-transform: uppercase;
    }

    .icon {
      width: 1em;
      height: 1em;
      flex: none;
      fill: currentColor;
    }

    /* Land acknowledgment and copyright. */
    .bottom {
      text-align: center;
    }

    .bottom p {
      margin: 0 0 16px;
    }

    .acknowledgment {
      font-style: italic;
      font-weight: 300;
    }

    .small {
      font-size: 14px;
    }

    .bottom .security {
      margin-bottom: 4px;
    }

    @media (min-width: 576px) {
      .container {
        max-width: 540px;
      }

      .top {
        justify-items: stretch;
        align-items: start;
      }

      .top > .logo {
        grid-column: span 5;
        margin-bottom: 30px;
      }

      .top > nav {
        grid-column: span 7;
      }

      .utility {
        justify-content: flex-end;
      }

      .columns > * {
        grid-column: span 6;
      }
    }

    @media (min-width: 768px) {
      .container {
        max-width: 720px;
      }

      .top > .logo {
        grid-column: span 4;
      }

      .top > nav {
        grid-column: span 8;
      }

      .columns > :nth-child(1) {
        grid-column: span 3;
      }

      .columns > :nth-child(2) {
        grid-column: span 5;
      }

      .columns > :nth-child(3),
      .columns > :nth-child(4) {
        grid-column: span 2;
      }

      .columns li {
        margin-bottom: 8px;
      }

      h2 {
        margin-top: 16px;
      }

      .topics ul {
        display: block;
        column-count: 2;
      }
    }

    @media (min-width: 992px) {
      .container {
        max-width: 960px;
      }
    }

    @media (min-width: 1200px) {
      .container {
        max-width: 1140px;
      }
    }

    @media (min-width: 1400px) {
      .container {
        max-width: 1320px;
      }
    }
  `;
	}
